INSERT INTO `archives` (`id`, `title`, `description`, `year`, `cover_image`, `status`, `created_at`, `updated_at`) VALUES
(4, 'সিনেটর প্রফেসর সাজিদ মীর পরিচিতি ও কর্মজীবন', 'সিনেটর প্রফেসর সাজিদ মীর\r\nআমীর–কেন্দ্রীয় জমিয়ত আহলে হাদীস, পাকিস্তান\r\nজন্ম: ২ অক্টোবর ১৯৩৮ | জন্মস্থান: সিয়ালকোট, পাঞ্জাব, পাকিস্তান\r\nপারিবারিক পরিচয়\r\nতিনি প্রখ্যাত ধর্মীয় ও রাজনৈতিক ব্যক্তিত্ব মাওলানা মোহাম্মদ ইব্রাহিম মীর সিয়ালকোটির বংশধর। তাঁর পিতা জনাব আবদুল কাইউম মীর ছিলেন শিক্ষা বিভাগের স্কুল পরিদর্শক।\r\nধর্মীয় ও আধুনিক শিক্ষা\r\nপ্রাথমিক শিক্ষা: পসরুর শহরে\r\nমেট্রিক: গর্ভনমেন্ট হাই স্কুল, সিয়ালকোট\r\nএফ.এ ও বি.এ: মারে কলেজ, সিয়ালকোট\r\nএম.এ (ইংরেজি): গর্ভনমেন্ট কলেজ, লাহোর\r\nএম.এ (ইসলামিয়াত): পাঞ্জাব বিশ্ববিদ্যালয় (১৯৬৯), প্রথম বিভাগ\r\nহাদীস শিক্ষা: জামিয়া তাকওয়াতুল ইমান, লাহোর\r\nহেফজুল কুরআন: শিক্ষাজীবনের প্রারম্ভেই সম্পন্ন\r\nঅন্যান্য শিক্ষাগত কৃতিত্ব\r\nবি.এ: রাজনীতি ও আরবি (১৯৫৮), ইংরেজি ও আরবিতে মেধাবৃত্তি\r\nঅতিরিক্ত বি.এ: অর্থনীতি (১৯৬৫), মনোবিজ্ঞান (১৯৬৬)\r\nপুরস্কার: মীর হাসান মেডেল, মোহাম্মদ আলী মেডেলসহ বিভিন্ন বিষয়ে পুরস্কারপ্রাপ্ত\r\nধর্মীয় যোগ্যতা\r\nফাযিল (দার্সে নিজামী): জামিয়া ইব্রাহিমিয়া, সিয়ালকোট (১৯৭১)\r\nফাযিল: দারুল উলুম তাকওয়াতুল ইসলাম, লাহোর (১৯৭২)\r\nআলিমিয়া কোর্স: ওয়েফাকুল মাদারিস সালাফিয়া\r\nপেশাগত জীবন\r\nলেকচারার (ইংরেজি): জিন্নাহ ইসলামিয়া কলেজ (১৯৬০–৬৩)\r\nপ্রশিক্ষক: পলিটেকনিক ইনস্টিটিউট, সিয়ালকোট (১৯৬৩–৬৬)\r\nসিনিয়র প্রশিক্ষক: লাহোর (১৯৬৬–৭৫)\r\nএডুকেশন অফিসার: নাইজেরিয়া ফেডারেল সরকার (১৯৭৫–৮৪)\r\nঅতিরিক্ত দায়িত্ব\r\nইনচার্জ – রিলেটেড স্টাডিজ বিভাগ, সিয়ালকোট\r\nএক্সামিনার – পাঞ্জাব টেকনিক্যাল বোর্ড\r\nনেতৃত্ব – পলিটেকনিক টিচার্স অ্যাসোসিয়েশন\r\nরাজনৈতিক ও দলীয় জীবন\r\nনাজিমে আ’লা: কেন্দ্রীয় জমিয়ত আহলে হাদীস (১৯৭৩)\r\nআমীর: টানা ৩২ বছরেরও বেশি সময় ধরে দায়িত্ব পালন\r\nসিনেটর: মোট ৬ বার নির্বাচিত (প্রথমবার ১৯৯৪)\r\nনেতৃত্ব দিয়েছেন:\r\nধর্ম বিষয়ক স্থায়ী কমিটি\r\nবিজ্ঞান ও প্রযুক্তি কমিটি\r\n\r\nকাশ্মীর ও গিলগিট-বালতিস্তান সংক্রান্ত কমিটি\r\nআন্তর্জাতিক অবদান ও প্রতিনিধিত্ব\r\nপ্রতিনিধিত্ব: আরব, ইউরোপ ও আমেরিকার বিভিন্ন আন্তর্জাতিক ইসলামিক কনফারেন্স\r\nসদস্য:\r\nরাবেতা আলমে ইসলামী (মক্কা)\r\nমাজলিসে ফিকহে ইসলামি\r\nপ্রতিষ্ঠাতা: আন্তর্জাতিক ইসলামিক টিভি চ্যানেল – পেয়গাম টিভি\r\nআন্তর্জাতিক সফর\r\nশহর: লন্ডন, নিউইয়র্ক, মক্কা, দিল্লি, বোম্বে, ইস্তাম্বুল ইত্যাদি\r\nদেশ: বেলজিয়াম, সুইজারল্যান্ড, ফ্রান্স, কানাডা, নাইজেরিয়া, স্পেন, গ্রীস প্রভৃতি\r\nসাহিত্যকর্ম ও অনুবাদ\r\nগ্রন্থ:\r\nখ্রিষ্টধর্ম: একটি বিশ্লেষণাত্মক গবেষণা\r\nঅনুবাদ ও সম্পাদনা:\r\nসহীহ মুসলিম\r\nমাযা খাসিরাল আলাম\r\nআল-হিযবুল মাকবুল (আরবি থেকে ইংরেজি)\r\nপ্রবন্ধ: শতাধিক প্রবন্ধ সাপ্তাহিক ও মাসিক পত্রিকায় প্রকাশিত\r\nচারিত্রিক বৈশিষ্ট্য\r\nসততা, সাহসিকতা ও বিশ্লেষণক্ষমতা\r\nবক্তৃতা ও লেখালেখিতে দক্ষ\r\nপারভেজ মোশাররফের একনায়কতন্ত্রের বিরুদ্ধে একক অবস্থানে অনড় – সাহসী নেতৃত্বের উজ্জ্বল দৃষ্টান্ত\r\nউপসংহার\r\nপ্রফেসর সাজিদ মীরের দূরদর্শী নেতৃত্বে জমিয়ত আহলে হাদীস, পাকিস্তান আজ একটি সুসংগঠিত ও প্রভাবশালী রাজনৈতিক-ধর্মীয় সংগঠনে পরিণত হয়েছে। দলের অধীনে সক্রিয় রয়েছে যুব, ছাত্র, আইনজীবী ও নারী শাখাসমূহ।\r\n\r\nঅনুবাদ ও সম্পাদনা:\r\nশাহরিয়ার হোসাইন\r\nঅর্থনীতি বিভাগ, ঢাকা বিশ্ববিদ্যালয়\r\nসদস্য, তুরাস একাডেমি', 2025, 'archives/UAclj9KcC5RBiqMFGFMtr6DTN5TiRCks3seM1buA.jpg', 1, '2025-05-04 21:00:04', '2025-05-05 10:29:33');

