INSERT INTO `galleries` (`id`, `title`, `description`, `path`, `is_featured`, `created_at`, `updated_at`) VALUES
(1, '১১তম সেশনের (২০২৫-২০২৭) নবনির্বাচিত দায়িত্বশীলদের হাতে দায়িত্ব অর্পণ', 'আলহামদুলিল্লাহ, তাওহীদি কাফেলা জমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ-এর ১১ তম সেশনের (২০২৫ - ২০২৭) নবনির্বাচিত দায়িত্বশীলদের হাতে দায়িত্ব অর্পণ করা হয়। মাননীয় জমঈয়ত সভাপতি অধ্যাপক ডক্টর আব্দুল্লাহ ফারুক দায়িত্ব হস্তান্তর বৈঠকে উপস্থিত থেকে নতুন দায়িত্বশীলদের জন্য দোয়া করেন। সদ্য বিদায়ী সভাপতি মুহা. আব্দুল্লাহ আল-ফারুক নবনির্বাচিত সভাপতি আব্দুল্লাহীল হাদী এবং সাধারণ সম্পাদক তানযীল আহমাদের নিকটে বিস্তারিত দায়িত্ব বুঝে দেন। এ সময় আবেগঘন পরিবেশের সৃষ্টি হয়। সকলেই সংগঠনের উত্তরোত্তর সাফল্যের জন্য মহান আল্লাহর নিকটে সাহায্য কামনা করেন।', 'gallery/2RXNhfBGELbbLSOXxdRcGx9G3VvgYzRBz0BWoQgf.jpg', 1, '2025-08-13 12:16:02', '2025-08-13 12:16:02');

