(4, 'general', 'notices/files/2xEPlEmwSVJvZUXFL6toKK8f5gwYO6vg78E862s5.pdf', 'notices/images/pN1R8V1yoMNOpPUU9Di20MbrOs6eW5xzZtdXCmfo.png', 'active', '2025-05-01 13:16:27', '2025-05-01 13:16:27', '{\"bn\":\"ওয়াকফ সংশোধনী নামক কালো আইনের বিরুদ্ধে তীব্র নিন্দা ও প্রতিবাদ\"}', '{\"bn\":\"ওয়াকফ সংশোধনী নামক কালো আইনের বিরুদ্ধে তীব্র নিন্দা ও প্রতিবাদ\"}'),
(5, 'general', 'notices/files/nAyP9ghRHuoIjBi7MLLrENb4mn6yKyqw2GMZdSCG.pdf', 'notices/images/v80h9PVAQpVoBUkf3YQRLIlBpQ4FKx80TzQ2QJYT.jpg', 'active', '2025-07-10 19:59:55', '2025-07-10 19:59:55', '{\"bn\":\"১১তম কেন্দ্রীয় সম্মেলন ২০২৫\"}', '{\"bn\":\"📣 ১১তম কেন্দ্রীয় সম্মেলন ২০২৫📣\\r\\nজাহেলিয়াতের বুনিয়াদ মোরা ভাঙ্গবোই\\r\\n📖 কুরআন ও সুন্নাহর পতাকা তলে ঐক্যবদ্ধ জাতি গঠন আমাদের নিরন্তর প্রয়াস\\r\\n🗓️ তারিখ: ০২ আগস্ট ২০২৫, শনিবার\\r\\n🕘 সময়: সকাল ৯:০০ টা\\r\\n📍 স্থান: আইডিইবি ভবন, ১৬০/এ, ভিআইপি রোড, কাকরাইল, ঢাকা-১২০৫\\r\\n🎙️ প্রধান অতিথি:\\r\\nঅধ্যাপক ড. আব্দুল্লাহ ফারুক\\r\\nসভাপতি, বাংলাদেশ জমঈয়তে আহলে হাদীস ও\\r\\nপ্রধান পৃষ্ঠপোষক, জমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ\\r\\n👤 সভাপতিত্ব করবেন:\\r\\nমুহা. আব্দুল্লাহ আল-ফারুক\\r\\nকেন্দ্রীয় সভাপতি, জমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ\\r\\n🤝 আমন্ত্রিত মেহমান:\\r\\nবরেণ্য উলামায়ে কেরাম, শিক্ষাবিদ, এবং জমঈয়ত ও শুব্বানের সর্বস্তরের দায়িত্বশীলবৃন্দ\\r\\n📢 আপনার উপস্থিতি সম্মেলনকে করবে আরো সার্থক ও প্রাণবন্ত। ইনশাআল্লাহ।\\r\\nজমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ\"}'),
(9, 'general', 'notices/files/5TejiynZZ0rNX97t8Bp0xJbmAlOhUOAPawjNxMw9.pdf', 'notices/images/rzHeVTdAAfBqTbjhGHDh3ZHsBrRrCrzyhtZWKils.jpg', 'active', '2025-07-13 19:19:31', '2025-07-13 19:19:31', '{\"bn\":\"ঢাকায় জাতিসংঘের মানবাধিকার অফিস চালু দেশের স্বাধীনতা সার্বভৌমত্বে ও ধর্মীয় বিষয়ে হস্তক্ষেপ জাতি মানবে না\"}', '{\"bn\":\"ঢাকায় জাতিসংঘের মানবাধিকার অফিস চালু দেশের স্বাধীনতা সার্বভৌমত্বে ও ধর্মীয় বিষয়ে হস্তক্ষেপ জাতি মানবে না\\r\\n\\r\\nজাতিসংঘের মানবাধিকার হাইকমিশনের অফিস রাজধানী ঢাকায় স্থাপনের নীতিগত সিদ্ধান্ত অন্তর্বর্তী সরকার নিয়েছে। ইতোমধ্যে বিভিন্ন ধর্মীয়, রাজনৈতিক সংগঠন, এমনকি বামপন্থী দলগুলোও এর প্রতিবাদ জানিয়েছে। মূলত জাতিসংঘের মানবাধিকার বিষয়ক হাইকমিশন বিভিন্ন দেশ এবং আঞ্চলে অফিস স্থাপন করে। স্থানীয় পর্যায়ের অফিসগুলো মানবাধিকার লঙ্ঘনের ঘটনা পর্যবেক্ষণ ও প্রতিবেদন তৈরি করে। কৌশলগত সহায়তা দেয়, সচেতনতার জন্য অ্যাডভোকেসি করে এবং মানবাধিকারকে স্থানীয়ভাবে আন্তর্জাতিক মানে নেয়ার চেষ্টাও করে।\\r\\n \\r\\nস্থানীয়ভাবে লিঙ্গ, আবাসন, ভূমি ব্যবস্থাপনা, বৈষম্য, স্বাস্থ্যসেবা ও বিশেষ চাহিদা সম্পন্ন মানুষদের ব্যাপারে গুরুত্ব দেয়াও জাতিসংঘের এই সংস্থার এজেন্ডার মধ্যে রয়েছে।\\r\\n\\t\\r\\nকিন্তু বাস্তব চিত্র হলো সম্পূর্ণ বিপরীত। বিশ্বের ১৪ টি দেশের মধ্যে ফিলিস্তিনেও তাদের অফিস আছে। অথচ শতাব্দীর নিশৃংসতম হত্যাযজ্ঞ সেখানে সংঘঠিত হলেও জাতিসংঘ এবং মানবাধিকার হাইকমিশনের অফিস নির্মম নিরবতা পালন করেছে। উপরন্তু বোদ্ধা মহল তাদের অন্যান্য দেশের কার্যক্রম পর্যালোচনা করে মনে করেন, এই অফিস তারা এখানে স্থাপন করলে সমকামিতা উৎসাহিত হবে। কাদিয়ানি, সংখ্যালঘু, পাহাড়ি, নানা ইস্যু তৈরি হবে। খ্রিস্টানদের প্রভাব বেড়ে যাবে। আর নারী স্বাধীনতার নামে তারা নারীদের ইসলামের বিধিবিধানের বাইরে নিয়ে যেতে কাজ করবে। এতে আমাদের মূল্যবোধ, দেশীয় সংস্কৃতিসহ আরো অনেক কিছু ক্ষতির মুখে পড়বে।\\r\\n\\t \\r\\nজমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ এই কাজের তীব্র নিন্দা ও প্রতিবাদ জানায়। সরকারের নিকট আবেদন জানায় যে, নব্বই ভাগ মুসলমানের দেশে এমন অফিস যেন কোনোভাবেই চালু না হয়। সেইসাথে দেশপ্রেমিক সকল মুসলিম নাগরিক ও সাধারণভাবে সকল দল মতের সকল স্তরের সচেতন দায়িত্বশীলের নিকটে আশাবাদ ব্যক্ত করে যে, এমন দূরভিসন্ধির বিরুদ্ধে আমরা সোচ্চার হই এবং দেশ ও ইসলাম বিরোধী এই চক্রান্তকে রুখে দেই।\\r\\n\\r\\nতানযীল আহমাদ \\r\\nযুগ্ম সাধারণ সম্পাদক\"}'),
(10, 'general', 'notices/files/YYpJ0EpPtCiP1z7HBoSDTduaeryjlZ0rv4I07hYd.pdf', 'notices/images/0Zma3oUuYvIL63QaDHnm7RTxsJPTzYD85jMfaFZb.jpg', 'active', '2025-07-28 18:03:13', '2025-07-28 18:03:13', '{\"bn\":\"১১তম কেন্দ্রীয় সম্মেলনের স্থান পরিবর্তন\"}', '{\"bn\":\"📢 জরুরি নোটিশ 📢\\r\\n🕌 ১১তম কেন্দ্রীয় সম্মেলনের স্থান পরিবর্তন\\r\\nসম্মেলনের স্থান পরিবর্তন করা হয়েছে।\\r\\n🔴 নতুন স্থান:\\r\\nজোনাকী কনভেনশন হল\\r\\n৬৯/১, নয়াপল্টন, ঢাকা।\\r\\n⏰ পূর্ব নির্ধারিত তারিখ ও সময় অনুযায়ী সম্মেলন অনুষ্ঠিত হবে।\"}');

