(4, 'photos/YnjMoc7HskhVJYpJ8TrfB7KKrS71Z5Id1j7Pi8jz.jpg', '{\"bn\":\"১১তম কেন্দ্রীয় সম্মেলন ২০২৫\"}', '{\"bn\":\"📣 ১১তম কেন্দ্রীয় সম্মেলন ২০২৫📣\\r\\nজাহেলিয়াতের বুনিয়াদ মোরা ভাঙ্গবোই\\r\\n📖 কুরআন ও সুন্নাহর পতাকা তলে ঐক্যবদ্ধ জাতি গঠন আমাদের নিরন্তর প্রয়াস\\r\\n🗓️ তারিখ: ০২ আগস্ট ২০২৫, শনিবার\\r\\n🕘 সময়: সকাল ৯:০০ টা\\r\\n📍 স্থান: আইডিইবি ভবন, ১৬০/এ, ভিআইপি রোড, কাকরাইল, ঢাকা-১২০৫\"}', 'conference-2025', '2025-07-10 04:00:00', '2025-07-10 15:41:21', '2025-07-10 15:41:21', 1, NULL, NULL),
(5, 'photos/4yZWun5oVSZhcmQN6ebiYLetv5EcjyxHbDJypaNT.jpg', '{\"bn\":\"১১তম কেন্দ্রীয় সম্মেলন ২০২৫\"}', '{\"bn\":\"📣 ১১তম কেন্দ্রীয় সম্মেলন ২০২৫📣\\r\\nজাহেলিয়াতের বুনিয়াদ মোরা ভাঙ্গবোই\\r\\n📖 কুরআন ও সুন্নাহর পতাকা তলে ঐক্যবদ্ধ জাতি গঠন আমাদের নিরন্তর প্রয়াস\\r\\n🗓️ তারিখ: ০২ আগস্ট ২০২৫, শনিবার\\r\\n🕘 সময়: সকাল ৯:০০ টা\\r\\n📍 স্থান: আইডিইবি ভবন, ১৬০/এ, ভিআইপি রোড, কাকরাইল, ঢাকা-১২০৫\"}', 'conference-2025', '2025-07-10 04:00:00', '2025-07-10 15:42:05', '2025-07-10 15:42:05', 1, NULL, NULL),
(6, 'photos/jp46bMf874FUMdPzaC3u5Zo61MK5BgVJZSQYUihs.jpg', '{\"bn\":\"১১তম কেন্দ্রীয় সম্মেলনের স্থান পরিবর্তন\"}', '{\"bn\":\"📢 জরুরি নোটিশ 📢\\r\\n🕌 ১১তম কেন্দ্রীয় সম্মেলনের স্থান পরিবর্তন\\r\\nসম্মেলনের স্থান পরিবর্তন করা হয়েছে।\\r\\n🔴 নতুন স্থান:\\r\\nজোনাকী কনভেনশন হল\\r\\n৬৯/১, নয়াপল্টন, ঢাকা।\\r\\n⏰ পূর্ব নির্ধারিত তারিখ ও সময় অনুযায়ী সম্মেলন অনুষ্ঠিত হবে।\"}', 'conference-2025', '2025-07-28 04:00:00', '2025-07-28 18:16:20', '2025-07-28 18:16:20', 1, NULL, NULL),
(7, 'photos/btyEo2B5vDxf9b8DhlWNlcIwV8cfqp2srKYTziHW.jpg', '{\"bn\":\"১১তম সেশনের (২০২৫-২০২৭) নবনির্বাচিত দায়িত্বশীলদের হাতে দায়িত্ব অর্পণ\"}', '{\"bn\":\"আলহামদুলিল্লাহ, তাওহীদি কাফেলা জমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ-এর ১১ তম সেশনের (২০২৫ - ২০২৭) নবনির্বাচিত দায়িত্বশীলদের হাতে দায়িত্ব অর্পণ করা হয়। মাননীয় জমঈয়ত সভাপতি অধ্যাপক ডক্টর আব্দুল্লাহ ফারুক দায়িত্ব হস্তান্তর বৈঠকে উপস্থিত থেকে নতুন দায়িত্বশীলদের জন্য দোয়া করেন। সদ্য বিদায়ী সভাপতি মুহা. আব্দুল্লাহ আল-ফারুক নবনির্বাচিত সভাপতি আব্দুল্লাহীল হাদী এবং সাধারণ সম্পাদক তানযীল আহমাদের নিকটে বিস্তারিত দায়িত্ব বুঝে দেন। এ সময় আবেগঘন পরিবেশের সৃষ্টি হয়। সকলেই সংগঠনের উত্তরোত্তর সাফল্যের জন্য মহান আল্লাহর নিকটে সাহায্য কামনা করেন।\"}', 'conference-2025', '2025-08-12 04:00:00', '2025-08-13 12:17:48', '2025-08-13 12:17:48', 1, NULL, NULL);

