(1, 'শুব্বান ডকুমেন্টারি-২০২৪', 'শুব্বান ডকুমেন্টারি-২০২৪', 'https://youtu.be/XbjhL2nWWy0', 'https://img.youtube.com/vi/XbjhL2nWWy0/maxresdefault.jpg', 'ডকুমেন্টারি', '2024-11-13', 1, '2025-04-24 09:15:13', '2025-04-24 09:15:13'),
(4, 'রমাযানের মাহাত্ম্য, আমাদের করণীয় শীর্ষক আলোচনা সভা ও ইফতার মফিল', 'মাযানের মাহাত্ম্য, আমাদের করণীয় শীর্ষক', 'https://youtu.be/7PwUSnTDqVM', 'https://img.youtube.com/vi/7PwUSnTDqVM/maxresdefault.jpg', 'ইফতার মফিল', '2025-03-22', 1, '2025-04-24 09:19:17', '2025-04-24 09:19:17'),
(5, 'দেশর সকল ষড়যন্ত্র রুখে দিতে শুব্বান সভাপতির আহ্বান', 'দেশর সকল ষড়যন্ত্র রুখে দিতে শুব্বান সভাপতির আহ্বান', 'https://youtu.be/wF_xgG83WzM', 'https://img.youtube.com/vi/wF_xgG83WzM/maxresdefault.jpg', 'বিশেষ ভিডিও', '2024-12-01', 1, '2025-04-24 09:24:11', '2025-04-24 09:24:11'),
(6, 'মহাসম্মেলন-২০২৪ | দিনাজপুর জেলা জমঈয়ত | মুহা. আব্দুল্লাহ আল-ফারুক', 'মহাসম্মেলন-২০২৪ | দিনাজপুর জেলা জমঈয়ত | মুহা. আব্দুল্লাহ আল-ফারুক', 'https://youtu.be/yZPdrk6Xomw', 'https://img.youtube.com/vi/yZPdrk6Xomw/maxresdefault.jpg', 'মহাসম্মেলন', '2024-11-24', 1, '2025-04-24 09:25:22', '2025-04-24 09:25:22'),
(7, 'ভাগা কুরবানি সকল আপত্তির নিরসন || তানযীল আহমাদ', 'ভাগা কুরবানি সকল আপত্তির নিরসন || তানযীল আহমাদ', 'https://youtu.be/662O7CW5wSs', 'https://img.youtube.com/vi/662O7CW5wSs/maxresdefault.jpg', 'কুরবানি', '2025-05-31', 1, '2025-05-31 15:02:22', '2025-05-31 15:02:22'),
(8, 'মুসলিম উম্মাহর বিভক্তি: আমাদের করণীয় ও বর্জনীয়', '📌 বিষয়: মুসলিম উম্মাহ\'র বিভক্তি: আমাদের করণীয় ও বর্জনীয়  \r\n🎙️  শাইখ মুহাম্মদ হারুন হুসাইন  \r\n📍 সিনিয়র যুগ্ম-সেক্রেটারি, বাংলাদেশ জমঈয়তে আহলে হাদীস  \r\n\r\n🔊 বর্তমান সময়ে মুসলিম উম্মাহ নানা কারণে বিভক্ত। এই বিভক্তির পিছনের কারণসমূহ, ইসলামের দৃষ্টিভঙ্গি, এবং উম্মাহর ঐক্যের প্রয়োজনীয়তা নিয়ে এই ভিডিওতে আলোচনা করা হয়েছে।', 'https://youtu.be/mTvjI6UQqbo', 'https://img.youtube.com/vi/mTvjI6UQqbo/maxresdefault.jpg', 'ফেজবুক লাইব', '2025-06-06', 1, '2025-06-18 14:45:03', '2025-06-18 14:45:03'),
(9, 'মুসলিম জীবনে হজ্জের গুরুত্ব ও শিক্ষা  |  শাইখ ড. মুযাফফর বিন মুহসিন', 'মাসিক আলোচনা সভা (৩৯তম পর্ব)\r\n🕋 বিষয়: মুসলিম জীবনে হজ্জের গুরুত্ব ও শিক্ষা \r\n\r\n🎙️ আলোচক: শাইখ ড. মুযাফফর বিন মুহসিন\r\nনির্বাহী সদস্য, বাংলাদেশ জমঈয়তে আহলে হাদীস\r\nপরিচালক, দারুল হুদা ইসলামী কমপ্লেক্স, রাজশাহী\r\n\r\n👤 সভাপতিত্ব করবেন: মুহা. আব্দুল্লাহ আল-ফারুক\r\nকেন্দ্রীয় সভাপতি, জমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ', 'https://youtu.be/7aP3RtvTxBo', 'https://img.youtube.com/vi/7aP3RtvTxBo/maxresdefault.jpg', 'মাসিক আলোচনা', '2025-06-20', 1, '2025-06-22 18:03:09', '2025-06-22 18:03:09'),
(10, '11th central conference 2025', '১১তম কেন্দ্রীয় সম্মেলন ২০২৫📣\r\nজাহেলিয়াতের বুনিয়াদ মোরা ভাঙ্গবোই\r\n📖 কুরআন ও সুন্নাহর পতাকা তলে ঐক্যবদ্ধ জাতি গঠন আমাদের নিরন্তর প্রয়াস\r\n🗓️ তারিখ: ০২ আগস্ট ২০২৫, শনিবার\r\n🕘 সময়: সকাল ৯:০০ টা\r\n📍 স্থান: আইডিইবি ভবন, ১৬০/এ, ভিআইপি রোড, কাকরাইল, ঢাকা-১২০৫\r\n🎙️ প্রধান অতিথি:\r\nঅধ্যাপক ড. আব্দুল্লাহ ফারুক\r\nসভাপতি, বাংলাদেশ জমঈয়তে আহলে হাদীস ও\r\nপ্রধান পৃষ্ঠপোষক, জমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ\r\n👤 সভাপতিত্ব করবেন:\r\nমুহা. আব্দুল্লাহ আল-ফারুক\r\nকেন্দ্রীয় সভাপতি, জমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ\r\n🤝 আমন্ত্রিত মেহমান:\r\nবরেণ্য উলামায়ে কেরাম, শিক্ষাবিদ, এবং জমঈয়ত ও শুব্বানের সর্বস্তরের দায়িত্বশীলবৃন্দ\r\n📢 আপনার উপস্থিতি সম্মেলনকে করবে আরো সার্থক ও প্রাণবন্ত। ইনশাআল্লাহ।\r\nজমঈয়ত শুব্বানে আহলে হাদীস বাংলাদেশ একটি ভিডিও ছারব ইনটো হিসো এর সাকল কিওয়াড তৈরি করে দাও', 'https://youtu.be/pkKWrTeN6e0', 'https://img.youtube.com/vi/pkKWrTeN6e0/maxresdefault.jpg', 'conference-2025', '2025-07-20', 1, '2025-07-20 12:26:55', '2025-07-20 12:52:57'),
(11, 'স্বাগত বক্তব্য || মুহা. আব্দুল্লাহ আল-ফারুক', NULL, 'https://youtu.be/MswYe0CYR14', 'https://img.youtube.com/vi/MswYe0CYR14/maxresdefault.jpg', 'conference-2025', '2025-08-11', 1, '2025-08-13 12:20:14', '2025-08-13 12:20:14');

